// TH16 v1.00a Extra: final boss 6th nonspell.
// Source: st07bs.ecl.txt Boss6 (594-654), dependency Boss6_at (656-679).
// Card frame 0 = control spawn; source frame 0 = timerReset at source line 607.

const TH16_SHARD: int = 512;            // source etSprite(0, 10, 14): type 10 = TH16_SHARD
const BULLET_COLOR: int = 14;

const TIME_LIMIT: int = 4324;           // 120 shell buffer + 4200 interrupt window + 4
const OPENING_BUFFER: int = 120;

// Boss6_at emit configuration (source 659-667).
const SHOT_WAYS: int = 3;               // etCount(0, 3, 3)
const SHOT_VOLLEYS: int = 100;          // $D = 100 at source 669
const SHOT_INTERVAL: int = 3;           // wait(3) at source 675
const SHOT_SPEED_0: fx = 4fx;           // etSpeed(0, 4, 3) over 3 layers: 4 / 3.5 / 3
const SHOT_SPEED_1: fx = 3.5fx;
const SHOT_SPEED_2: fx = 3fx;
// etDist 32 along each bullet angle, minus the ANIM(a=1) birth pullback 4*speed.
const SHOT_DIST_0: fx = 16fx;
const SHOT_DIST_1: fx = 18fx;
const SHOT_DIST_2: fx = 20fx;
const SHOT_OFFSET_Y: fx = -24fx;        // etOffset(0, 0, -24) at source 667

// moveRand(60, 4, 1.9) inside moveLimit(0, 128, 240, 64) (source 635, 645, 649).
const MOVE_SPEED: fx = 1.9fx;
const MOVE_FRAMES: int = 60;
const MOVE_LIMIT_X: fx = 120fx;         // full width 240 -> x in [-120, 120]
const MOVE_LIMIT_TOP: fx = 96fx;        // full height 64 around y=128
const MOVE_LIMIT_BOTTOM: fx = 160fx;
const MOVE_INNER_X: fx = 60fx;          // direction pick uses centre +- quarter size
const MOVE_INNER_TOP: fx = 112fx;
const MOVE_INNER_BOTTOM: fx = 144fx;

// ---------------------------------------------------------------------------
// Boss6_at (source 656-679): fixed 3-way ring, 3 speed layers, base angle
// rotated by the `dir` argument after every volley.
// ---------------------------------------------------------------------------
async sub boss6_at(dir: angle) {
    sh_reset(0);
    sh_sprite(0, TH16_SHARD, BULLET_COLOR);   // etSprite(0, 10, 14)
    sh_ring(0, 1);                            // etAim(0, 3): fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, SHOT_WAYS, 1);                // etCount(0, 3, 3)
    sh_angle(0, 0deg, 0deg);                  // etAngle(0, 0, 0)
    sh_offset(0, 0fx, SHOT_OFFSET_Y);
    var base: angle = aim_player();           // %C = %ANGLE_PLAYER
    for volley in 0..SHOT_VOLLEYS {
        sh_angle(0, base, 0deg);
        sh_speed(0, SHOT_SPEED_0, 0fx);
        sh_dist(0, SHOT_DIST_0);
        sh_fire(0);
        sh_speed(0, SHOT_SPEED_1, 0fx);
        sh_dist(0, SHOT_DIST_1);
        sh_fire(0);
        sh_speed(0, SHOT_SPEED_2, 0fx);
        sh_dist(0, SHOT_DIST_2);
        sh_fire(0);
        base = base + dir;                    // %C = %C + %A
        wait(SHOT_INTERVAL);
    }
}

// ---------------------------------------------------------------------------
// moveRand replay (movement.md recipe, speed 1.9, moveLimit 240x64).
// Enemy int slot 0 = next step index; fx slots 0/1 = logical unit direction.
// ---------------------------------------------------------------------------
sub arm_next_move() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < MOVE_FRAMES {
        speed = MOVE_SPEED * ((MOVE_FRAMES - k) as fx / MOVE_FRAMES as fx);
    }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -MOVE_LIMIT_X { nx = -MOVE_LIMIT_X; }
    if nx > MOVE_LIMIT_X { nx = MOVE_LIMIT_X; }
    if ny < MOVE_LIMIT_TOP { ny = MOVE_LIMIT_TOP; }
    if ny > MOVE_LIMIT_BOTTOM { ny = MOVE_LIMIT_BOTTOM; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_move();
}

// Source 412: one signed direction sample per call, source frame of the call
// still reads the old position; movement ticks run for the following 60 frames.
sub move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -MOVE_INNER_X {
        a = r / 3;
    } else if $self_x > MOVE_INNER_X {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < MOVE_INNER_TOP {
        if a < 0 { a = -a; }
    } else if $self_y > MOVE_INNER_BOTTOM {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_angle(a as angle);
}

// Source waits that overlap the moveRand motion.
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_move();
    }
}

// ---------------------------------------------------------------------------
// Boss6 entry (source 594-654).
// ---------------------------------------------------------------------------
async sub source_enemy() {
    set_invuln(65535);
    set_hitbox(24fx);                    // Boss() setHitbox(48, 48): 48*0.5
    set_hurtbox(20fx);                   // Boss() setHurtbox(40, 40): 40*0.5
    // 596-637 handover/stats/presentation omitted per policy (entry clears,
    // kill-all, item drops, sounds, anim, life marker, interrupt slot).
    // timerReset at 607 is source frame 0.
    wait(120);                           // 634
    wait(60);                            // 638, moveLimit applied by move_rand
    loop {
        spawn boss6_at(8deg);            // 643 Boss6_at(0.13962634, ...)
        wait(100);                       // 644
        move_rand();                     // 645 moveRand(60, 4, 1.9)
        card_wait(60);                   // 646
        spawn boss6_at(-8deg);           // 647 Boss6_at(-0.13962634, ...)
        wait(100);                       // 648
        move_rand();                     // 649
        card_wait(60);                   // 650
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 14000, 0, 0, 0, source_enemy);   // entry at (0,128)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    // Source handover to BossCard6 is out of scope: the attack ends here, so the
    // real boss leaves silently (spawn_enemy tasks are not phase-bound).
    kill_all_enemies(KILL_SILENT);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
